        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def safe_power(base, exp):
    """
    Calculates base^exp, returning None if the result is not a well-defined integer.
    Handles typical integer arithmetic rules, including $0^0=1$ convention.
    """
    try:
        if base == 0:
            if exp == 0:
                return 1  # Convention for 0^0
            elif exp > 0:
                return 0
            else: # exp < 0
                return None # 0 raised to negative power is undefined

        # Standard integer power calculation
        result = pow(base, exp)

        # Since we are checking for prime (an integer), we ensure the result is an integer
        if isinstance(result, int):
            return result
        else:
            # This handles cases like (-1/2)^2 if it somehow arose, though unlikely here
            return None

    except OverflowError:
        return None
    except Exception:
        return None

